inline int64_t StampMeasure( const Stamp & value )
{
    int64_t bytes = 2; // terminator
    if ( value.tag_length < 0 || value.tag_length > 8 ) { return -1; } // storage invariant
    if ( value.tag_length > 0 ) { bytes += 3 + 4 + value.tag_length; } // tag
    if ( value.seq != 0 ) { bytes += 3 + 4; } // seq
    return bytes;
}

inline bool StampSaveBody( TableWriter & w, const Stamp & value )
{
    if ( value.tag_length < 0 || value.tag_length > 8 ) { return false; } // storage invariant
    if ( value.tag_length > 0 )
    {
        w.put16( 0xbc64 ); w.put8( 12 ); // tag
        w.put32( uint32_t( value.tag_length ) );
        w.raw( value.tag, value.tag_length );
    }
    if ( value.seq != 0 )
    {
        w.put16( 0xc29b ); w.put8( 4 ); // seq
        w.put32( uint32_t( value.seq ) );
    }
    w.put16( 0 ); // terminator
    return !w.overflow;
}

inline int64_t StampSave( const Stamp & value, uint8_t * buffer, int64_t capacity )
{
    TableWriter w( buffer, capacity );
    if ( !StampSaveBody( w, value ) ) { return -1; }
    return w.offset; // == StampMeasure( value )
}

inline bool StampLoadBody( TableReader & r, Stamp & value )
{
    StampReset( value ); // prefill declared defaults in place, then overlay
    for ( ;; )
    {
        if ( !r.has( 2 ) ) { r.report->malformed = true; return false; }
        uint16_t field_id = r.get16();
        if ( field_id == 0 ) return true;
        if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
        uint8_t kind = r.get8();
        switch ( field_id )
        {
            case 0xbc64: // tag
            {
                if ( kind != 12 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t len = r.get32();
                if ( !r.has( len ) ) { r.report->malformed = true; return false; }
                uint32_t keep = len;
                if ( keep > 8 ) { keep = 8; r.report->clamped++; }
                memcpy( value.tag, r.buffer + r.offset, keep );
                value.tag[keep] = 0;
                value.tag_length = (int32_t) keep;
                r.offset += len;
                break;
            }
            case 0xc29b: // seq
            {
                if ( kind != 4 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                int32_t decoded_v = int32_t( r.get32( ) );
                if ( decoded_v < 0 ) { decoded_v = 0; r.report->clamped++; }
                else if ( decoded_v > 1000 ) { decoded_v = 1000; r.report->clamped++; }
                value.seq = decoded_v;
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                break;
            }
        }
    }
}

inline bool StampLoad( Stamp & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReader r( buffer, bytes, report != NULL ? report : &ignored );
    return StampLoadBody( r, value );
}

inline int64_t ColourMeasure( const Colour & value )
{
    int64_t bytes = 2; // terminator
    if ( value.r != 0 ) { bytes += 3 + 1; } // r
    if ( value.g != 0 ) { bytes += 3 + 1; } // g
    if ( value.b != 0 ) { bytes += 3 + 1; } // b
    return bytes;
}

inline bool ColourSaveBody( TableWriter & w, const Colour & value )
{
    if ( value.r != 0 )
    {
        w.put16( 0xb019 ); w.put8( 6 ); // r
        w.put8( uint8_t( value.r ) );
    }
    if ( value.g != 0 )
    {
        w.put16( 0xc40a ); w.put8( 6 ); // g
        w.put8( uint8_t( value.g ) );
    }
    if ( value.b != 0 )
    {
        w.put16( 0xcae9 ); w.put8( 6 ); // b
        w.put8( uint8_t( value.b ) );
    }
    w.put16( 0 ); // terminator
    return !w.overflow;
}

inline int64_t ColourSave( const Colour & value, uint8_t * buffer, int64_t capacity )
{
    TableWriter w( buffer, capacity );
    if ( !ColourSaveBody( w, value ) ) { return -1; }
    return w.offset; // == ColourMeasure( value )
}

inline bool ColourLoadBody( TableReader & r, Colour & value )
{
    ColourReset( value ); // prefill declared defaults in place, then overlay
    for ( ;; )
    {
        if ( !r.has( 2 ) ) { r.report->malformed = true; return false; }
        uint16_t field_id = r.get16();
        if ( field_id == 0 ) return true;
        if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
        uint8_t kind = r.get8();
        switch ( field_id )
        {
            case 0xb019: // r
            {
                if ( kind != 6 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
                uint8_t decoded_v = uint8_t( r.get8( ) );
                value.r = decoded_v;
                break;
            }
            case 0xc40a: // g
            {
                if ( kind != 6 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
                uint8_t decoded_v = uint8_t( r.get8( ) );
                value.g = decoded_v;
                break;
            }
            case 0xcae9: // b
            {
                if ( kind != 6 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
                uint8_t decoded_v = uint8_t( r.get8( ) );
                value.b = decoded_v;
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                break;
            }
        }
    }
}

inline bool ColourLoad( Colour & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReader r( buffer, bytes, report != NULL ? report : &ignored );
    return ColourLoadBody( r, value );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
// A pointer FIELD is a TableRef — four bytes and no address — so the
// property holds in BOTH forms: a fixed-size table is one relocatable
// struct, and a packed region is one relocatable block whose references
// are self-relative and therefore survive a plain memcpy.
static_assert( std::is_trivially_copyable<Stamp>::value, "Stamp must stay relocatable" );
static_assert( std::is_standard_layout<Stamp>::value, "Stamp must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<Colour>::value, "Colour must stay relocatable" );
static_assert( std::is_standard_layout<Colour>::value, "Colour must stay standard-layout for offsetof" );

// ---- reflection descriptors (tables only, SPEC-TABLES.md) ----

inline const TableTypeInfo * StampTableType();
inline const TableTypeInfo * ColourTableType();
// The descriptors are CONSTANT-INITIALISED data, and a field's target is
// the ADDRESS of another descriptor. These declarations are what let a
// self- or mutually-referential graph — Node naming itself through *Node —
// be expressed as constant data instead of a lazy link, which could not
// have been written race-free OR recursion-safe. The whole reflection
// surface is therefore immutable: read it from any thread, any time.
extern const TableTypeInfo StampTableInfo;
extern const TableTypeInfo ColourTableInfo;

inline const TableFieldInfo StampTableFields[] = {
    { "tag", "tag", "string", 0xbc64, 12, false, false, true, false, 8, (uint32_t) offsetof( Stamp, tag ), (uint32_t) sizeof( Stamp::tag ), (uint32_t) offsetof( Stamp, tag_length ), 0xffffffffu, NULL, false, 0.0, 0.0, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
    { "seq", "seq", "int32", 0xc29b, 4, false, false, false, false, 0, (uint32_t) offsetof( Stamp, seq ), (uint32_t) sizeof( Stamp::seq ), 0xffffffffu, 0xffffffffu, NULL, true, 0.0, 1000.0, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
};
inline const TableTypeInfo StampTableInfo = { "Stamp", (uint32_t) sizeof( Stamp ), 2, StampTableFields, +[]( void * p ) { StampReset( *(Stamp *) p ); }, false };
inline const TableTypeInfo * StampTableType() { return &StampTableInfo; }

inline const TableFieldInfo ColourTableFields[] = {
    { "r", "r", "uint8", 0xb019, 6, false, false, false, false, 0, (uint32_t) offsetof( Colour, r ), (uint32_t) sizeof( Colour::r ), 0xffffffffu, 0xffffffffu, NULL, false, 0.0, 0.0, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
    { "g", "g", "uint8", 0xc40a, 6, false, false, false, false, 0, (uint32_t) offsetof( Colour, g ), (uint32_t) sizeof( Colour::g ), 0xffffffffu, 0xffffffffu, NULL, false, 0.0, 0.0, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
    { "b", "b", "uint8", 0xcae9, 6, false, false, false, false, 0, (uint32_t) offsetof( Colour, b ), (uint32_t) sizeof( Colour::b ), 0xffffffffu, 0xffffffffu, NULL, false, 0.0, 0.0, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
};
inline const TableTypeInfo ColourTableInfo = { "Colour", (uint32_t) sizeof( Colour ), 3, ColourTableFields, +[]( void * p ) { ColourReset( *(Colour *) p ); }, false };
inline const TableTypeInfo * ColourTableType() { return &ColourTableInfo; }

